import 'package:flutter/material.dart';class FuturisticAppBar extends StatelessWidget implements PreferredSizeWidget{final String title;final List<Widget> actions;const FuturisticAppBar({super.key,required this.title,this.actions=const[]});@override Widget build(BuildContext c)=>AppBar(backgroundColor:Colors.transparent,elevation:0,foregroundColor:Colors.white,title:Text(title,style:const TextStyle(fontWeight:FontWeight.w800)),actions:actions);@override Size get preferredSize=>const Size.fromHeight(kToolbarHeight);}